/** Quiet, photo-backed calendar. All forms use the same store as the agent and widgets. */
public final class CalendarActivity extends Activity {
    private CalendarStore store;private FrameLayout root;private LinearLayout body;private boolean dark,list;private int ink,muted;private LocalDate selected=LocalDate.now();private YearMonth month=YearMonth.now();private Dialog editor;private View feedback;private Runnable hideFeedback;
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    protected void onCreate(Bundle state){int theme=getSharedPreferences("home",0).getInt("theme",0);dark=theme==2||(theme==0&&(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);setTheme(dark?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);super.onCreate(state);store=new CalendarStore(this);ink=dark?0xFFE7F0EC:0xFF243F37;muted=dark?0xFFADBFBC:0xFF61776F;
        if(state!=null){selected=LocalDate.parse(state.getString("selected",selected.toString()));month=YearMonth.parse(state.getString("month",month.toString()));list=state.getBoolean("list");}else try{selected=LocalDate.parse(getIntent().getStringExtra("date"));month=YearMonth.from(selected);}catch(Exception ignored){}
        getWindow().setDecorFitsSystemWindows(false);getWindow().setStatusBarColor(Color.TRANSPARENT);getWindow().setNavigationBarColor(Color.TRANSPARENT);
        root=new FrameLayout(this);ImageView backdrop=new ImageView(this);backdrop.setImageResource(dark?R.drawable.home_starfield:R.drawable.home_mist_mountains);backdrop.setScaleType(ImageView.ScaleType.CENTER_CROP);root.addView(backdrop,new FrameLayout.LayoutParams(-1,-1));
        View wash=new View(this);wash.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{dark?0x44081828:0x55F3F6E7,dark?0xDD142A34:0xDDEDF3E9}));root.addView(wash,new FrameLayout.LayoutParams(-1,-1));root.addView(new CalendarGlints(this,dark),new FrameLayout.LayoutParams(-1,-1));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(22),0,dp(22),dp(24));scroll.addView(body);root.addView(scroll,new FrameLayout.LayoutParams(-1,-1));
        root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets safe=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());scroll.setPadding(safe.left,safe.top,safe.right,safe.bottom);return insets;});setContentView(root);WindowInsetsController bars=getWindow().getInsetsController();if(bars!=null)bars.setSystemBarsAppearance(dark?0:WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS);
        try{if(getIntent().hasExtra("show_cycle")){JSONObject p=store.preferences();p.put("id","calendar-preferences").put("expected_revision",p.optInt("revision")).put("show_cycle",getIntent().getBooleanExtra("show_cycle",false));store.write("preferences",p,UUID.randomUUID().toString());}}catch(Exception e){error(e);}
        render();root.post(()->{try{String item=getIntent().getStringExtra("item");if(getIntent().getBooleanExtra("cycle_setup",false)){cycleSettings();return;}if(item!=null&&!item.isEmpty()){JSONObject record=store.get(item);if(record!=null&&!record.optBoolean("deleted"))eventEditor(record);else Toast.makeText(this,"这条记录已删除",Toast.LENGTH_SHORT).show();}else if(getIntent().getBooleanExtra("add",false))chooseAdd();}catch(Exception e){error(e);}});
    }
    protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("selected",selected.toString());b.putString("month",month.toString());b.putBoolean("list",list);}
    protected void onResume(){super.onResume();if(store!=null)render();CalendarUpdates.changed(this);}
    protected void onDestroy(){if(hideFeedback!=null)root.removeCallbacks(hideFeedback);if(editor!=null)editor.dismiss();store.close();super.onDestroy();}
    private TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(ink);return v;}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));d.setStroke(dp(1),dark?0x22FFFFFF:0x18284936);return d;}
    private LinearLayout row(){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);return r;}
    private TextView button(String value,String label,Runnable action){TextView b=text(value,20);b.setGravity(Gravity.CENTER);b.setContentDescription(label);b.setMinHeight(dp(44));b.setOnClickListener(v->action.run());b.setLayoutParams(new LinearLayout.LayoutParams(dp(44),dp(44)));return b;}
    private TextView heading(String value,int size){TextView t=text(value,size);t.setPadding(0,dp(18),0,dp(12));body.addView(t);return t;}
    private void changeMonth(int delta){month=month.plusMonths(delta);selected=month.atDay(Math.min(selected.getDayOfMonth(),month.lengthOfMonth()));render();}
    private void render(){try{
        body.removeAllViews();boolean cycle=store.preferences().optBoolean("show_cycle");LinearLayout top=row();top.addView(button("‹","返回",this::finish));TextView title=text("日历",23);top.addView(title,new LinearLayout.LayoutParams(0,dp(58),1));title.setGravity(Gravity.CENTER_VERTICAL);TextView female=button("♀",cycle?"隐藏大姨妈内容":"显示大姨妈内容",()->{try{JSONObject setting=store.settings();if(!cycle&&!setting.optBoolean("enabled")&&store.cycles().isEmpty()){cycleSettings();return;}JSONObject p=store.preferences();p.put("id","calendar-preferences").put("expected_revision",p.optInt("revision")).put("show_cycle",!cycle);store.write("preferences",p,UUID.randomUUID().toString());render();}catch(Exception e){error(e);}});if(cycle)female.setBackground(shape(dark?0x33375B44:0x33386B53,22));top.addView(female);top.addView(button("＋","添加日期",this::chooseAdd));top.addView(button("⋯","日历设置",this::settingsMenu));body.addView(top);
        LinearLayout months=row();TextView name=text(month.getMonthValue()+"月  "+month.getYear(),27);months.addView(name,new LinearLayout.LayoutParams(0,dp(62),1));name.setGravity(Gravity.CENTER_VERTICAL);months.addView(button("‹","上个月",()->changeMonth(-1)));months.addView(button("›","下个月",()->changeMonth(1)));body.addView(months);
        LinearLayout tabs=row();TextView a=text(list?"月历":"月历  ─",13),b=text(list?"日期列表  ─":"日期列表",13);a.setPadding(0,dp(8),dp(20),dp(15));b.setPadding(0,dp(8),0,dp(15));a.setOnClickListener(v->{list=false;render();});b.setOnClickListener(v->{list=true;render();});tabs.addView(a);tabs.addView(b);body.addView(tabs);
        if(!list){CalendarMonthView grid=new CalendarMonthView(this);grid.bind(month,selected,dark,cycle,store,date->{selected=date;if(!YearMonth.from(date).equals(month))month=YearMonth.from(date);render();});grid.setMonthChangeListener(this::changeMonth);grid.setBackground(shape(dark?0xCC182D39:0xCCF1F5E7,22));body.addView(grid,new LinearLayout.LayoutParams(-1,-2));TextView legend=text(cycle?"粉色底 · 大姨妈（虚线为预计）\n绿字 · 其他周期日期　紫字 · 预计易孕期　✿ · 预计排卵日":"日期下方的小点表示重要日子",11);legend.setTextColor(muted);legend.setPadding(dp(3),dp(10),0,dp(6));body.addView(legend);heading(selected+" · 农历"+CalendarDates.lunar(selected).label(),13);showDay(selected,cycle);}
        JSONArray events=store.events(list?month.atDay(1):LocalDate.now(),list?month.atEndOfMonth():LocalDate.now().plusYears(1));heading(list?"本月重要日期":"接下来的日子",14);
        if(cycle){JSONObject p=store.prediction();if(p.optBoolean("available")){long days=CalendarDates.days(LocalDate.now(),LocalDate.parse(p.getString("next_start")));String subtitle=p.optBoolean("variable")?"预计 "+p.optString("range_start")+" 至 "+p.optString("range_end")+" · 周期波动较大":"预计 "+p.getString("next_start")+" · 仅供记录参考";entry("下次大姨妈",days<0?"尚未记录本次开始":days==0?"预计今天":days+"天后",subtitle,this::cycleSettings);}}
        for(int i=0;i<Math.min(100,events.length());i++){JSONObject e=events.getJSONObject(i);long days=e.getLong("days_until");entry(e.getString("title"),days==0?"就是今天":days<0?"已过"+(-days)+"天":days+"天后",e.getString("occurrence")+("lunar".equals(e.optString("calendar"))?" · 农历"+CalendarDates.lunar(LocalDate.parse(e.getString("date"))).label():"")+(e.optBoolean("count_up")?" · 已经"+e.optLong("elapsed_days")+"天":""),()->eventEditor(e));}
        if(!list)for(JSONObject e:store.items("event")){if(e.optBoolean("count_up")){LocalDate base=LocalDate.parse(e.getString("date"));long days=CalendarDates.days(base,LocalDate.now());entry(e.getString("title"),days<0?(-days)+"天后开始":"已经"+days+"天",base+"起",()->eventEditor(e));}}
        if(events.length()==0)entry("留住一个值得记住的日子","＋","点击添加，也可以直接对 Greta 说",()->eventEditor(null));
        AppTypography.apply(body);
    }catch(Exception e){error(e);}}
    private void showDay(LocalDate d,boolean cycle)throws Exception{
        JSONArray events=store.events(d,d);for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);entry(e.getString("title"),"今天",e.optString("note"),()->eventEditor(e));}
        if(cycle){boolean actual=false;for(JSONObject r:store.cycles()){LocalDate a=LocalDate.parse(r.getString("start")),b=LocalDate.parse(r.optString("end",LocalDate.now().toString()));if(!d.isBefore(a)&&!d.isAfter(b)){actual=true;entry("大姨妈第"+(CalendarDates.days(a,d)+1)+"天","已记录",r.optString("note"),()->cycleEditor(r));}}
            JSONObject p=store.prediction();if(!actual&&p.optBoolean("available")&&!d.isBefore(LocalDate.parse(p.getString("next_start")))&&!d.isAfter(LocalDate.parse(p.getString("next_end"))))entry("预计大姨妈","预计","尚未记录本次开始",this::cycleSettings);
            if(!actual&&p.has("ovulation")&&d.toString().equals(p.optString("ovulation")))entry("预计排卵日","预计","仅为日期估算，不能作为避孕依据",this::cycleSettings);else if(!actual&&p.has("fertile_start")&&!d.isBefore(LocalDate.parse(p.getString("fertile_start")))&&!d.isAfter(LocalDate.parse(p.getString("fertile_end"))))entry("预计易孕期","预计","仅为日期估算，不能作为避孕依据",this::cycleSettings);}
    }
    private void entry(String title,String right,String detail,Runnable action){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(0,dp(14),0,dp(14));LinearLayout line=row();TextView a=text(title,16);line.addView(a,new LinearLayout.LayoutParams(0,-2,1));TextView b=text(right,17);b.setPadding(dp(12),0,0,0);line.addView(b);box.addView(line);if(!detail.isEmpty()){TextView sub=text(detail,12);sub.setTextColor(muted);sub.setPadding(0,dp(5),0,0);box.addView(sub);}box.setOnClickListener(v->action.run());body.addView(box,new LinearLayout.LayoutParams(-1,-2));View divider=new View(this);divider.setBackgroundColor(dark?0x1CFFFFFF:0x18284936);body.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));}
    private LinearLayout sheet(String title){if(editor!=null)editor.dismiss();editor=new Dialog(this,dark?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(24),dp(22),dp(24),dp(28));form.setBackground(shape(dark?0xFF162B33:0xFFF0F5ED,28));TextView heading=text(title,23);form.addView(heading);return form;}
    private void showSheet(LinearLayout form){AppTypography.apply(form);FormKeyboard.showSheet(editor,form);}
    private EditText field(LinearLayout form,String label,String value,int type){TextView name=text(label,12);name.setTextColor(muted);name.setPadding(0,dp(17),0,dp(5));form.addView(name);EditText input=new EditText(this);input.setText(value);input.setTextColor(ink);input.setTextSize(16);input.setSingleLine(type!=android.text.InputType.TYPE_CLASS_TEXT);input.setInputType(type);form.addView(input,new LinearLayout.LayoutParams(-1,-2));return input;}
    private Spinner options(LinearLayout form,String label,String[] choices,int selected){TextView name=text(label,12);name.setTextColor(muted);name.setPadding(0,dp(14),0,dp(4));form.addView(name);Spinner s=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,choices);s.setAdapter(adapter);s.setSelection(selected);form.addView(s,new LinearLayout.LayoutParams(-1,dp(44)));return s;}
    private Switch toggle(LinearLayout form,String label,boolean checked){Switch s=new Switch(this);s.setText(label);s.setTextColor(ink);s.setTextSize(14);s.setPadding(0,dp(14),0,dp(10));s.setChecked(checked);form.addView(s);return s;}
    private TextView dateField(LinearLayout form,String label,LocalDate[] date){TextView name=text(label,12);name.setTextColor(muted);name.setPadding(0,dp(16),0,0);form.addView(name);TextView v=text(date[0]+"  ·  农历"+CalendarDates.lunar(date[0]).label(),16);v.setPadding(0,dp(10),0,dp(10));v.setOnClickListener(x->{DatePickerDialog picker=new DatePickerDialog(this,(view,y,m,d)->{date[0]=LocalDate.of(y,m+1,d);v.setText(date[0]+"  ·  农历"+CalendarDates.lunar(date[0]).label());},date[0].getYear(),date[0].getMonthValue()-1,date[0].getDayOfMonth());picker.show();});form.addView(v);return v;}
    private void saveButton(LinearLayout form,Runnable action){TextView save=text("保存",16);save.setTextColor(dark?0xFF18342B:Color.WHITE);save.setGravity(Gravity.CENTER);save.setPadding(dp(20),dp(12),dp(20),dp(12));save.setBackground(shape(dark?0xFFBCDACA:0xFF38694F,24));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.gravity=Gravity.END;p.topMargin=dp(22);form.addView(save,p);save.setOnClickListener(v->action.run());}
    private void saved(JSONObject result){
        if(editor!=null)editor.dismiss();render();if(feedback!=null)root.removeView(feedback);if(hideFeedback!=null)root.removeCallbacks(hideFeedback);
        LinearLayout pill=row();pill.setPadding(dp(16),dp(4),dp(6),dp(4));pill.setBackground(shape(dark?0xFF203A40:0xFFF0F5ED,24));TextView label=text(result.optString("summary"),13);label.setMaxLines(2);pill.addView(label,new LinearLayout.LayoutParams(0,-2,1));TextView undo=text("撤销",13);undo.setGravity(Gravity.CENTER);pill.addView(undo,new LinearLayout.LayoutParams(dp(58),dp(44)));undo.setOnClickListener(v->{try{store.undo(result.getString("operation_id"),UUID.randomUUID().toString());root.removeView(pill);render();Toast.makeText(this,"已撤销",Toast.LENGTH_SHORT).show();}catch(Exception e){error(e);}});
        FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);lp.setMargins(dp(22),0,dp(22),dp(26));WindowInsets insets=root.getRootWindowInsets();if(insets!=null)lp.bottomMargin+=insets.getInsets(WindowInsets.Type.systemBars()).bottom;root.addView(pill,lp);feedback=pill;hideFeedback=()->{root.removeView(pill);if(feedback==pill)feedback=null;};root.postDelayed(hideFeedback,8000);AppTypography.apply(pill);
    }
    private void chooseAdd(){new AlertDialog.Builder(this).setItems(new String[]{"重要日期","大姨妈开始／结束","大姨妈周期设置"},(d,n)->{if(n==0)eventEditor(null);else if(n==1)cycleEditor(null);else cycleSettings();}).show();}
    private void eventEditor(JSONObject original){try{
        JSONObject e=original==null?new JSONObject():new JSONObject(original.toString());LinearLayout form=sheet(original==null?"留住一个日子":"编辑重要日期");EditText title=field(form,"名称",e.optString("title"),android.text.InputType.TYPE_CLASS_TEXT);LocalDate[] date={LocalDate.parse(e.optString("date",selected.toString()))};TextView dateLabel=dateField(form,"日期（公历日期选择，可切换农历输入）",date);
        Spinner calendar=options(form,"历法",new String[]{"公历","农历"},"lunar".equals(e.optString("calendar"))?1:0);TextView lunarButton=text("按农历月日选择 ›",14);lunarButton.setTextColor(muted);lunarButton.setPadding(0,dp(10),0,dp(10));lunarButton.setOnClickListener(v->lunarPicker(date,dateLabel));form.addView(lunarButton);
        Switch unknown=toggle(form,"只记月日，不记录出生／起始年份",original==null||!e.optBoolean("year_known",true));Switch yearly=toggle(form,"每年重复",e.optBoolean("yearly",true)),countUp=toggle(form,"显示已经多少天",e.optBoolean("count_up"));
        yearly.setOnCheckedChangeListener((v,checked)->{unknown.setEnabled(checked);if(!checked)unknown.setChecked(false);});unknown.setEnabled(yearly.isChecked());countUp.setOnCheckedChangeListener((v,checked)->{if(checked)unknown.setChecked(false);});
        LinearLayout advanced=new LinearLayout(this);advanced.setOrientation(1);form.removeView(countUp);advanced.addView(countUp);
        Spinner leap=options(advanced,"2月29日遇到非闰年",new String[]{"2月28日","3月1日"},"march1".equals(e.optString("leap_day"))?1:0),missing=options(advanced,"农历缺日／闰月规则",new String[]{"缺少三十时用月末；缺少闰月时跳过","缺少该日期的年份跳过","闰月缺失时用同名普通月"},"skip".equals(e.optString("missing_day"))?1:"regular".equals(e.optString("missing_day"))?2:0);
        EditText milestone=field(advanced,"可选：第几天纪念（起始日为第0天）",e.has("milestone")?e.optString("milestone"):"",android.text.InputType.TYPE_CLASS_NUMBER);
        Switch remind=toggle(form,"提醒我",e.optBoolean("remind",true));EditText ahead=field(form,"提前天数",e.optString("remind_days","1"),android.text.InputType.TYPE_CLASS_NUMBER),time=field(form,"提醒时间 HH:mm",e.optString("remind_time","09:00"),android.text.InputType.TYPE_CLASS_DATETIME),note=field(advanced,"备注",e.optString("note"),android.text.InputType.TYPE_CLASS_TEXT);
        Switch followZone=toggle(advanced,"提醒时间跟随所在地",e.optBoolean("follow_timezone",true));EditText zone=field(advanced,"固定提醒时区（关闭跟随后生效）",e.optString("timezone",ZoneId.systemDefault().getId()),android.text.InputType.TYPE_CLASS_TEXT);
        TextView more=text("更多选项 ›",13);more.setTextColor(muted);more.setPadding(0,dp(18),0,dp(8));more.setOnClickListener(v->{boolean show=advanced.getVisibility()!=View.VISIBLE;advanced.setVisibility(show?View.VISIBLE:View.GONE);more.setText(show?"收起选项 ‹":"更多选项 ›");});form.addView(more);advanced.setVisibility(View.GONE);form.addView(advanced);
        saveButton(form,()->{try{JSONObject change=new JSONObject().put("title",title.getText().toString().trim()).put("date",date[0].toString()).put("calendar",calendar.getSelectedItemPosition()==0?"solar":"lunar").put("yearly",yearly.isChecked()).put("count_up",countUp.isChecked()).put("year_known",!unknown.isChecked()).put("leap_day",leap.getSelectedItemPosition()==0?"feb28":"march1").put("missing_day",new String[]{"last_day","skip","regular"}[missing.getSelectedItemPosition()]).put("remind",remind.isChecked()).put("remind_days",Integer.parseInt(ahead.getText().toString())).put("remind_time",time.getText().toString().trim()).put("timezone",zone.getText().toString().trim()).put("follow_timezone",followZone.isChecked()).put("note",note.getText().toString());CalendarDates.Lunar lunar=CalendarDates.lunar(date[0]);change.put("lunar_month",lunar.month).put("lunar_day",lunar.day).put("lunar_leap",lunar.leap);if(!milestone.getText().toString().isEmpty())change.put("milestone",Integer.parseInt(milestone.getText().toString()));else if(e.has("milestone"))change.put("milestone",JSONObject.NULL);if(e.has("id"))change.put("id",e.getString("id")).put("expected_revision",e.getInt("revision"));JSONObject result=store.write("event",change,UUID.randomUUID().toString());if(remind.isChecked())notificationPermission();saved(result);}catch(Exception ex){error(ex);}});
        deleteButton(form,e,"event");showSheet(form);
    }catch(Exception ex){error(ex);}}
    private void lunarPicker(LocalDate[] date,TextView label){CalendarDates.Lunar lunar=CalendarDates.lunar(date[0]);LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(20),dp(10),dp(20),dp(10));TextView desc=text("选择农历月日，年份沿用已选日期的公历年",13);panel.addView(desc);LinearLayout pickers=row();NumberPicker m=new NumberPicker(this),d=new NumberPicker(this);m.setMinValue(1);m.setMaxValue(12);m.setValue(lunar.month);d.setMinValue(1);d.setMaxValue(30);d.setValue(lunar.day);pickers.addView(m,new LinearLayout.LayoutParams(0,-2,1));pickers.addView(d,new LinearLayout.LayoutParams(0,-2,1));panel.addView(pickers);Switch leap=toggle(panel,"闰月",lunar.leap);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("农历日期").setView(panel).setPositiveButton("确定",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(x->{LocalDate found=m.getValue()==lunar.month&&d.getValue()==lunar.day&&leap.isChecked()==lunar.leap?date[0]:CalendarDates.lunarInYear(date[0].getYear(),m.getValue(),d.getValue(),leap.isChecked(),"skip");if(found==null){Toast.makeText(this,"该公历年没有这个农历日期，请调整年份或日期",Toast.LENGTH_LONG).show();return;}date[0]=found;label.setText(found+" · 农历"+CalendarDates.lunar(found).label());dialog.dismiss();}));dialog.show();}
    private void cycleEditor(JSONObject original){try{
        JSONObject e=original==null?new JSONObject():new JSONObject(original.toString());LinearLayout form=sheet("记录大姨妈");LocalDate[] start={LocalDate.parse(e.optString("start",selected.isAfter(LocalDate.now())?LocalDate.now().toString():selected.toString()))},end={LocalDate.parse(e.optString("end",LocalDate.now().toString()))};dateField(form,"实际开始日期",start);Switch ended=toggle(form,"本次已经结束",e.has("end"));dateField(form,"实际结束日期（未结束时不会保存）",end);EditText note=field(form,"备注／身体感受",e.optString("note"),android.text.InputType.TYPE_CLASS_TEXT);
        saveButton(form,()->{try{JSONObject change=new JSONObject().put("start",start[0].toString()).put("end",ended.isChecked()?end[0].toString():JSONObject.NULL).put("note",note.getText().toString());if(e.has("id"))change.put("id",e.getString("id")).put("expected_revision",e.getInt("revision"));saved(store.write("cycle",change,UUID.randomUUID().toString()));}catch(Exception ex){error(ex);}});deleteButton(form,e,"cycle");showSheet(form);
    }catch(Exception ex){error(ex);}}
    private void cycleSettings(){try{
        JSONObject old=store.settings();LinearLayout form=sheet("大姨妈周期设置");TextView intro=text("周期是两次开始之间的间隔。预测仅供记录参考，不能作为避孕依据。",13);intro.setTextColor(muted);intro.setPadding(0,dp(10),0,0);form.addView(intro);Switch enabled=toggle(form,"启用预测",old.has("id")?old.optBoolean("enabled"):true);EditText length=field(form,"通常周期天数",old.optString("cycle_days",""),android.text.InputType.TYPE_CLASS_NUMBER),duration=field(form,"通常持续天数",old.optString("duration",""),android.text.InputType.TYPE_CLASS_NUMBER);LocalDate[] first={LocalDate.now()};boolean empty=store.cycles().isEmpty();if(empty)dateField(form,"最近一次实际开始（首次配置时保存）",first);
        Switch adaptive=toggle(form,"有至少3个完整周期间隔后，根据历史调整",old.optBoolean("adaptive")),remind=toggle(form,"预计到来前提醒",old.optBoolean("remind",true));EditText ahead=field(form,"提前天数",old.optString("remind_days","2"),android.text.InputType.TYPE_CLASS_NUMBER),time=field(form,"提醒时间 HH:mm",old.optString("remind_time","09:00"),android.text.InputType.TYPE_CLASS_DATETIME);Switch ai=toggle(form,"允许 AI 查询和修改大姨妈数据",old.optBoolean("ai_access",true));TextView disclosure=text("主动问询时，相关记录会发送给你配置的 AI 服务；不会加入普通导出。",12);disclosure.setTextColor(muted);form.addView(disclosure);
        Switch followZone=toggle(form,"提醒时间跟随所在地",old.optBoolean("follow_timezone",true));EditText zone=field(form,"固定提醒时区（关闭跟随后生效）",old.optString("timezone",ZoneId.systemDefault().getId()),android.text.InputType.TYPE_CLASS_TEXT);
        saveButton(form,()->{try{JSONObject change=new JSONObject().put("id","cycle-settings").put("expected_revision",old.optInt("revision")).put("enabled",enabled.isChecked()).put("adaptive",adaptive.isChecked()).put("remind",remind.isChecked()).put("remind_days",Integer.parseInt(ahead.getText().toString())).put("remind_time",time.getText().toString().trim()).put("timezone",zone.getText().toString().trim()).put("follow_timezone",followZone.isChecked()).put("ai_access",ai.isChecked());if(!length.getText().toString().isEmpty())change.put("cycle_days",Integer.parseInt(length.getText().toString()));if(!duration.getText().toString().isEmpty())change.put("duration",Integer.parseInt(duration.getText().toString()));JSONObject result=store.configure(change,empty&&enabled.isChecked()?first[0].toString():null,enabled.isChecked(),UUID.randomUUID().toString());if(remind.isChecked())notificationPermission();saved(result);}catch(Exception ex){error(ex);}});
        TextView history=text("查看／修正历史记录 ›",14);history.setPadding(0,dp(18),0,0);history.setOnClickListener(v->cycleHistory());form.addView(history);showSheet(form);
    }catch(Exception ex){error(ex);}}
    private void cycleHistory(){try{java.util.List<JSONObject> records=store.cycles();Collections.reverse(records);String[] labels=new String[records.size()];for(int i=0;i<labels.length;i++)labels[i]=records.get(i).optString("start")+" → "+records.get(i).optString("end","尚未记录结束");new AlertDialog.Builder(this).setTitle("大姨妈实际记录").setItems(labels,(d,n)->cycleEditor(records.get(n))).setNegativeButton("关闭",null).show();}catch(Exception e){error(e);}}
    private void deleteButton(LinearLayout form,JSONObject e,String kind){if(!e.has("id"))return;TextView delete=text("删除这条记录",13);delete.setTextColor(muted);delete.setPadding(0,dp(22),0,0);delete.setOnClickListener(v->{try{saved(store.write(kind,new JSONObject().put("id",e.getString("id")).put("expected_revision",e.getInt("revision")).put("deleted",true),UUID.randomUUID().toString()));}catch(Exception ex){error(ex);}});form.addView(delete);}
    private void notificationPermission(){if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},84);}
    public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==84)CalendarUpdates.changed(this);}
    private void settingsMenu(){new AlertDialog.Builder(this).setItems(new String[]{"大姨妈周期与提醒","实际记录历史","查看全部重要日期","桌面组件","私密通知内容","日历通知设置"},(d,n)->{if(n==0)cycleSettings();if(n==1)cycleHistory();if(n==2)allEvents();if(n==3)widgetHelp();if(n==5)startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));if(n==4)try{JSONObject p=store.preferences();p.put("id","calendar-preferences").put("expected_revision",p.optInt("revision")).put("private_notifications",!p.optBoolean("private_notifications",true));store.write("preferences",p,UUID.randomUUID().toString());Toast.makeText(this,p.optBoolean("private_notifications")?"大姨妈通知已隐藏详情":"大姨妈通知将显示详情",Toast.LENGTH_LONG).show();}catch(Exception ex){error(ex);}}).show();}
    private void allEvents(){try{java.util.List<JSONObject> events=store.items("event");String[] names=new String[events.size()];for(int i=0;i<names.length;i++)names[i]=events.get(i).optString("title")+" · "+events.get(i).optString("date");new AlertDialog.Builder(this).setTitle("全部重要日期").setItems(names,(d,n)->eventEditor(events.get(n))).setNegativeButton("关闭",null).show();}catch(Exception e){error(e);}}
    private void widgetHelp(){AppWidgetManagerPin.show(this);}
    private void error(Exception e){String message=e instanceof NumberFormatException?"天数请填写有效的整数":e instanceof java.time.DateTimeException?"日期或时间格式无效，时间请填写为 09:00":e.getMessage()==null?"暂时无法完成，请重试":e.getMessage();Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    private static final class AppWidgetManagerPin {static void show(Activity a){new AlertDialog.Builder(a).setTitle("添加桌面组件").setItems(new String[]{"大月历","近期日期","单个纪念日"},(d,n)->{android.appwidget.AppWidgetManager m=android.appwidget.AppWidgetManager.getInstance(a);Class<?> cls=n==0?CalendarWidget.class:n==1?CalendarWidget.Agenda.class:CalendarWidget.Countdown.class;if(m.isRequestPinAppWidgetSupported()){
                    Intent config=new Intent(a,CalendarWidgetSettingsActivity.class).setData(android.net.Uri.parse("greta-calendar://configure/"+cls.getSimpleName()));
                    PendingIntent callback=PendingIntent.getActivity(a,cls.getName().hashCode(),config,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);
                    m.requestPinAppWidget(new ComponentName(a,cls),null,callback);
                }else Toast.makeText(a,"长按桌面 → 微件 → Greta，选择日历组件",Toast.LENGTH_LONG).show();}).setNegativeButton("取消",null).show();}}
}
